import concurrent.futures, json, re, subprocess, urllib.parse

def clean(s):
    s=re.sub(r'(?i)(bearer\s+)[A-Za-z0-9._~+/=-]+',r'\1[REDACTED]',s)
    s=re.sub(r'(?i)((?:password|passwd|token|secret|api[_-]?key)\s*[:=]\s*[\"\']?)[^\s\"\',;&]+',r'\1[REDACTED]',s)
    return re.sub(r'(https?://)[^/@\s]+:[^/@\s]+@',r'\1[REDACTED]@',s)
def api(label,base,params):
    path=base+'?'+urllib.parse.urlencode(params,quote_via=urllib.parse.quote)
    return label,['teamcity','api',path,'-X','GET','--raw','-H','Accept: application/json','--no-input']
items=[]
for n in [482190,482191]:
    items.extend([
      api(f'{n}_identity_and_dependency_count',f'/app/rest/builds/id:{n}',{'fields':'id,buildTypeId,state,status,buildType(id,projectId),snapshot-dependencies(count)'}),
      api(f'{n}_immediate_dependencies','/app/rest/builds',{'locator':f'snapshotDependency:(to:(id:{n}),recursive:false),defaultFilter:false,count:20','fields':'count,nextHref,build(id,buildTypeId,state,status,buildType(id,projectId))'}),
      api(f'{n}_problems','/app/rest/problemOccurrences',{'locator':f'build:(id:{n}),count:20','fields':'count,nextHref,problemOccurrence(id,type,identity,details,build(id))'}),
      api(f'{n}_failed_unmuted_tests','/app/rest/testOccurrences',{'locator':f'build:(id:{n}),status:FAILURE,muted:false,count:20','fields':'count,nextHref,testOccurrence(id,name,status,muted,ignored,details,build(id),test(id))'}),
      api(f'{n}_failed_muted_tests','/app/rest/testOccurrences',{'locator':f'build:(id:{n}),status:FAILURE,muted:true,count:20','fields':'count,nextHref,testOccurrence(id,name,status,muted,ignored,details,build(id),test(id))'}),
      api(f'{n}_changes','/app/rest/changes',{'locator':f'build:(id:{n}),count:10','fields':'count,nextHref,change(id,version,username,date,comment)'}),
      (f'{n}_log_tail',['teamcity','run','log',str(n),'--tail','80','--json','--no-input'])])
def run(item):
    label,cmd=item
    try:
        p=subprocess.run(cmd,text=True,capture_output=True,timeout=60)
        return {'source':label,'exit_code':p.returncode,'stdout':clean(p.stdout),'stderr':clean(p.stderr)}
    except subprocess.TimeoutExpired:
        return {'source':label,'error':'request timed out after 60 seconds'}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
    for result in pool.map(run,items):
        print(json.dumps(result))
